import json

# Read the last few entries from 2026-06-08
with open('/root/.nanobot/request_logs/2026-06-08.jsonl') as f:
    lines = f.readlines()

# Check the last 3 entries for context issues
for entry_idx in range(-3, 0):
    line = lines[entry_idx].strip()
    try:
        d = json.loads(line)
        msgs = d.get('messages', [])
        print(f'=== Entry {entry_idx}: {len(msgs)} messages ===')

        issues = []
        prev_role = None
        for i, m in enumerate(msgs):
            role = m.get('role','?')
            content = m.get('content','')
            if isinstance(content, list):
                text_parts = [p.get('text','') for p in content if isinstance(p, dict) and p.get('type') == 'text']
                preview = ' '.join(text_parts)[:80].replace('\n',' ')
            else:
                preview = str(content)[:80].replace('\n',' ')

            if role == 'assistant' and prev_role == 'assistant':
                issues.append(f'  ⚠️ [{i-1}]->[{i}] CONSECUTIVE ASSISTANT')
            if role == 'tool' and prev_role not in ('assistant', 'tool'):
                issues.append(f'  ⚠️ [{i}] ORPHAN TOOL after {prev_role}')

            if i < 5 or i > len(msgs)-5 or role in ('user', 'tool') or (role == 'assistant' and prev_role == 'assistant'):
                print(f'  [{i:2d}] {role:12s} len={len(str(content)):5d} | {preview}')
            prev_role = role

        if issues:
            print('  ISSUES:', len(issues))
            for iss in issues[:5]:
                print(iss)
        else:
            print('  No issues found')
        print()
    except Exception as e:
        print(f'Error parsing entry: {e}')
